input.query:
SELECT "Protein class", "RNA tissue specificity", "RNA tissue specific nTPM", "Secretome location", "Cancer prognostics - Breast Invasive Carcinoma (TCGA)"
FROM proteinatlas
LIMIT 5;

SELECT Gene, "Gene description", "Protein class", "RNA tissue specificity", "RNA tissue specific nTPM", "Secretome location", "Cancer prognostics - Breast Invasive Carcinoma (TCGA)"
FROM proteinatlas
WHERE Gene IN ('ENSG00000101843', 'ENSG00000120265', 'ENSG00000156110', 'ENSG00000164494');

SELECT Gene, Ensembl, "Protein class", "RNA tissue specificity", "RNA tissue specific nTPM", "Secretome location", "Cancer prognostics - Breast Invasive Carcinoma (TCGA)"
FROM proteinatlas
WHERE Ensembl IN ('ENSG00000101843', 'ENSG00000120265', 'ENSG00000156110', 'ENSG00000164494');

SELECT Gene, "Gene name", "validated prognostic - unfavorable" 
FROM cancer_prognostic_data 
WHERE Cancer = 'Breast Invasive Carcinoma (validation)' AND "validated prognostic - unfavorable" IS NOT NULL AND "validated prognostic - unfavorable" != '';

SELECT Gene, Ensembl, "Protein class", "RNA tissue specificity", "RNA tissue specific nTPM", "Secretome location", "Cancer prognostics - Breast Invasive Carcinoma (TCGA)", "Blood concentration - Conc. blood IM [pg/L]", "Blood concentration - Conc. blood MS [pg/L]"
FROM proteinatlas
WHERE "Cancer prognostics - Breast Invasive Carcinoma (TCGA)" LIKE '%validated%unfavor%';
